/*
 * Output and update for action system:
 *    '<S986>/CircularPrediction'
 *    '<S1315>/CircularPrediction'
 *    '<S1811>/CircularPrediction'
 */
void LongSafe_SWC_CircularPrediction(const ObjGroup1Vcc *rtu_Obj, const
  SafetyMarginData *rtu_SafetyMarginData, real32_T rtu_PredictionTime, const
  BoundingBox0 *rtu_BoundingBox, real32_T *rty_PredObjAgDir, real32_T
  *rty_PredObjMotion, real32_T *rty_PredObjMotion_m, real32_T
  *rty_PredObjMotion_l, real32_T *rty_PredObjMotion_g, real32_T
  *rty_PredObjMotion_h, real32_T *rty_PredObjMotion_p, const
  ConstB_CircularPrediction_LongSafe_SWC_T *localC)
{
  real32_T rtb_NewPosnLat_h;
  real32_T rtb_NewPosnLgt_j;
  real32_T rtb_PredictedHeading;
  real32_T rtb_Product_mb;
  real32_T rtb_Quotient_o2;
  real32_T rtb_TransformedLat;
  real32_T rtb_TransformedLgt;
  real32_T rtb_TrigonometricFunction1_f;
  real32_T rtb_TrigonometricFunction3_ab;
  boolean_T rtb_RelationalOperator_dp;

  /* Outputs for Atomic SubSystem: '<S1043>/SafeDivide' */
  /* MATLAB Function: '<S1047>/SafeDivide' */
  if (fabsf(rtu_SafetyMarginData->A) > fabsf(rtu_Obj->Estimn.Spd) *
      5.42101151E-20F) {
    rtb_Quotient_o2 = rtu_Obj->Estimn.Spd / rtu_SafetyMarginData->A;
  } else if (rtu_Obj->Estimn.Spd > 0.0F) {
    rtb_Quotient_o2 = LongSafe_SWC_DataTypeMax;
  } else if (rtu_Obj->Estimn.Spd < 0.0F) {
    rtb_Quotient_o2 = LongSafe_SWC_DataTypeMin;
  } else {
    rtb_Quotient_o2 = 0.0F;
  }

  /* End of MATLAB Function: '<S1047>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S1043>/SafeDivide' */

  /* Gain: '<S1043>/Gain' */
  rtb_NewPosnLat_h = rtCP_Gain_Gain_b * rtb_Quotient_o2;

  /* Switch: '<S1043>/Switch' incorporates:
   *  Constant: '<S1046>/Constant'
   *  MinMax: '<S1043>/MinMax'
   *  RelationalOperator: '<S1046>/Compare'
   */
  if (rtb_NewPosnLat_h > rtCP_Constant_Value_dii) {
    rtb_NewPosnLat_h = fminf(rtu_PredictionTime, rtb_NewPosnLat_h);
  } else {
    rtb_NewPosnLat_h = rtu_PredictionTime;
  }

  /* End of Switch: '<S1043>/Switch' */

  /* Product: '<S1028>/Divide3' incorporates:
   *  Constant: '<S1028>/Constant'
   *  Constant: '<S1042>/Constant'
   *  Product: '<S1042>/Product1'
   *  Product: '<S1042>/Product4'
   *  Product: '<S1042>/Product5'
   *  Sum: '<S1042>/Sum6'
   */
  rtb_TrigonometricFunction3_ab = (rtb_NewPosnLat_h * rtb_NewPosnLat_h *
    rtu_SafetyMarginData->A * rtCP_Constant_Value_hb + (rtu_Obj->Estimn.Spd *
    rtb_NewPosnLat_h + rtCP_Constant_Value_dl)) * rtu_SafetyMarginData->Crvt;

  /* Sum: '<S1028>/Add9' */
  rtb_PredictedHeading = rtb_TrigonometricFunction3_ab + rtu_Obj->Estimn.AgDir;

  /* SignalConversion: '<S1026>/Signal Conversion' */
  *rty_PredObjAgDir = rtb_PredictedHeading;

  /* RelationalOperator: '<S1044>/Relational Operator' incorporates:
   *  Abs: '<S1044>/Abs'
   *  Constant: '<S1044>/LimitSource'
   *  Sum: '<S1032>/Add'
   */
  rtb_RelationalOperator_dp = (fabsf(rtu_PredictionTime - rtb_NewPosnLat_h) >
    rtCP_LimitSource_Value);

  /* Switch: '<S1032>/Switch1' incorporates:
   *  Constant: '<S1032>/Constant1'
   *  Product: '<S1042>/Product6'
   *  Sum: '<S1042>/Sum3'
   */
  if (rtb_RelationalOperator_dp) {
    rtb_NewPosnLat_h = rtCP_Constant1_Value_kh;
  } else {
    rtb_NewPosnLat_h = rtb_NewPosnLat_h * rtu_SafetyMarginData->A +
      rtu_Obj->Estimn.Spd;
  }

  /* End of Switch: '<S1032>/Switch1' */

  /* Product: '<S1029>/Product4' incorporates:
   *  Product: '<S1029>/Product7'
   */
  rtb_NewPosnLgt_j = rtb_NewPosnLat_h * rtu_SafetyMarginData->Crvt *
    rtb_NewPosnLat_h;

  /* Trigonometry: '<S1029>/Trigonometric Function1' incorporates:
   *  Trigonometry: '<S1028>/Trigonometric Function3'
   */
  rtb_Quotient_o2 = sinf(rtb_PredictedHeading);

  /* Trigonometry: '<S1029>/Trigonometric Function' incorporates:
   *  Trigonometry: '<S1028>/Trigonometric Function2'
   */
  rtb_PredictedHeading = cosf(rtb_PredictedHeading);

  /* Switch: '<S1032>/Switch' incorporates:
   *  Constant: '<S1032>/Constant'
   */
  if (rtb_RelationalOperator_dp) {
    rtb_TransformedLat = rtCP_Constant_Value_pvn;
  } else {
    rtb_TransformedLat = rtu_SafetyMarginData->A;
  }

  /* End of Switch: '<S1032>/Switch' */

  /* Sum: '<S1029>/Add' incorporates:
   *  Product: '<S1029>/Product'
   *  Product: '<S1029>/Product1'
   *  Trigonometry: '<S1029>/Trigonometric Function'
   *  Trigonometry: '<S1029>/Trigonometric Function1'
   */
  *rty_PredObjMotion_l = rtb_PredictedHeading * rtb_TransformedLat -
    rtb_NewPosnLgt_j * rtb_Quotient_o2;

  /* Product: '<S1029>/Product5' incorporates:
   *  Trigonometry: '<S1029>/Trigonometric Function1'
   */
  *rty_PredObjMotion_h = rtb_Quotient_o2 * rtb_NewPosnLat_h;

  /* Product: '<S1029>/Product6' incorporates:
   *  Trigonometry: '<S1029>/Trigonometric Function'
   */
  *rty_PredObjMotion_m = rtb_NewPosnLat_h * rtb_PredictedHeading;

  /* Sum: '<S1029>/Subtract' incorporates:
   *  Product: '<S1029>/Product2'
   *  Product: '<S1029>/Product3'
   *  Trigonometry: '<S1029>/Trigonometric Function'
   *  Trigonometry: '<S1029>/Trigonometric Function1'
   */
  *rty_PredObjMotion_p = rtb_Quotient_o2 * rtb_TransformedLat +
    rtb_PredictedHeading * rtb_NewPosnLgt_j;

  /* Sum: '<S1030>/Add1' incorporates:
   *  Constant: '<S1030>/Constant1'
   */
  rtb_TransformedLat = rtu_Obj->Estimn.AgDir + rtCP_Constant1_Value_l;

  /* Outputs for Atomic SubSystem: '<S1038>/SafeDivide' */
  /* MATLAB Function: '<S1039>/SafeDivide' incorporates:
   *  Constant: '<S1030>/Constant2'
   */
  if (fabsf(rtu_SafetyMarginData->Crvt) > fabsf(rtCP_Constant2_Value_g) *
      5.42101151E-20F) {
    rtb_NewPosnLgt_j = rtCP_Constant2_Value_g / rtu_SafetyMarginData->Crvt;
  } else if (rtCP_Constant2_Value_g > 0.0F) {
    rtb_NewPosnLgt_j = LongSafe_SWC_DataTypeMax;
  } else if (rtCP_Constant2_Value_g < 0.0F) {
    rtb_NewPosnLgt_j = LongSafe_SWC_DataTypeMin;
  } else {
    rtb_NewPosnLgt_j = 0.0F;
  }

  /* End of MATLAB Function: '<S1039>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S1038>/SafeDivide' */

  /* Switch: '<S1040>/Switch' incorporates:
   *  RelationalOperator: '<S1040>/UpperRelop'
   */
  if (rtb_NewPosnLgt_j < localC->Gain) {
    rtb_NewPosnLat_h = localC->Gain;
  } else {
    rtb_NewPosnLat_h = rtb_NewPosnLgt_j;
  }

  /* End of Switch: '<S1040>/Switch' */

  /* Switch: '<S1040>/Switch2' incorporates:
   *  Constant: '<S1038>/Constant5'
   *  RelationalOperator: '<S1040>/LowerRelop1'
   */
  if (rtb_NewPosnLgt_j > rtCP_Constant5_Value_j) {
    rtb_NewPosnLat_h = rtCP_Constant5_Value_j;
  }

  /* End of Switch: '<S1040>/Switch2' */

  /* Signum: '<S1028>/Sign' */
  if (rtu_Obj->Estimn.Spd < 0.0F) {
    rtb_NewPosnLgt_j = -1.0F;
  } else if (rtu_Obj->Estimn.Spd > 0.0F) {
    rtb_NewPosnLgt_j = 1.0F;
  } else if (rtu_Obj->Estimn.Spd == 0.0F) {
    rtb_NewPosnLgt_j = 0.0F;
  } else {
    rtb_NewPosnLgt_j = (rtNaNF);
  }

  /* End of Signum: '<S1028>/Sign' */

  /* Product: '<S1028>/Product' */
  rtb_Product_mb = rtu_BoundingBox->LengthSideLgt * rtb_NewPosnLgt_j;

  /* RelationalOperator: '<S1028>/Relational Operator' incorporates:
   *  Constant: '<S1031>/Constant'
   */
  rtb_RelationalOperator_dp = (rtu_Obj->Info.MtnPat == rtCP_Constant_Value_d5);

  /* Switch: '<S1028>/Switch2' incorporates:
   *  Product: '<S1037>/Product2'
   *  Sum: '<S1037>/Add2'
   *  Trigonometry: '<S1028>/Trigonometric Function1'
   */
  if (rtb_RelationalOperator_dp) {
    rtb_TransformedLgt = rtu_Obj->Estimn.PosnLgt - rtb_Product_mb * cosf
      (rtu_Obj->Estimn.AgDir);
  } else {
    rtb_TransformedLgt = rtu_Obj->Estimn.PosnLgt;
  }

  /* End of Switch: '<S1028>/Switch2' */

  /* Sum: '<S1030>/Add' incorporates:
   *  Product: '<S1030>/Divide'
   *  Trigonometry: '<S1030>/Trigonometric Function'
   */
  rtb_NewPosnLgt_j = cosf(rtb_TransformedLat) * rtb_NewPosnLat_h +
    rtb_TransformedLgt;

  /* Trigonometry: '<S1030>/Trigonometric Function1' */
  rtb_TrigonometricFunction1_f = sinf(rtb_TransformedLat);

  /* Switch: '<S1028>/Switch1' incorporates:
   *  Product: '<S1035>/Product2'
   *  Sum: '<S1035>/Add2'
   *  Trigonometry: '<S1028>/Trigonometric Function'
   */
  if (rtb_RelationalOperator_dp) {
    rtb_TransformedLat = rtu_Obj->Estimn.PosnLat - rtb_Product_mb * sinf
      (rtu_Obj->Estimn.AgDir);
  } else {
    rtb_TransformedLat = rtu_Obj->Estimn.PosnLat;
  }

  /* End of Switch: '<S1028>/Switch1' */

  /* Sum: '<S1030>/Add2' incorporates:
   *  Product: '<S1030>/Divide2'
   */
  rtb_NewPosnLat_h = rtb_NewPosnLat_h * rtb_TrigonometricFunction1_f +
    rtb_TransformedLat;

  /* Sum: '<S1033>/Add3' */
  rtb_TransformedLgt -= rtb_NewPosnLgt_j;

  /* Sum: '<S1033>/Add4' */
  rtb_TransformedLat -= rtb_NewPosnLat_h;

  /* Trigonometry: '<S1033>/Trigonometric Function2' */
  rtb_TrigonometricFunction1_f = cosf(rtb_TrigonometricFunction3_ab);

  /* Trigonometry: '<S1033>/Trigonometric Function3' */
  rtb_TrigonometricFunction3_ab = sinf(rtb_TrigonometricFunction3_ab);

  /* Sum: '<S1033>/Add7' incorporates:
   *  Product: '<S1033>/Divide4'
   *  Product: '<S1033>/Divide6'
   *  Sum: '<S1033>/Add5'
   */
  rtb_NewPosnLgt_j += rtb_TransformedLgt * rtb_TrigonometricFunction1_f -
    rtb_TransformedLat * rtb_TrigonometricFunction3_ab;

  /* Sum: '<S1033>/Add8' incorporates:
   *  Product: '<S1033>/Divide5'
   *  Product: '<S1033>/Divide7'
   *  Sum: '<S1033>/Add6'
   */
  rtb_NewPosnLat_h += rtb_TransformedLgt * rtb_TrigonometricFunction3_ab +
    rtb_TransformedLat * rtb_TrigonometricFunction1_f;

  /* Switch: '<S1028>/Switch3' incorporates:
   *  Product: '<S1034>/Product2'
   *  Product: '<S1036>/Product2'
   *  Sum: '<S1034>/Add2'
   *  Sum: '<S1036>/Add2'
   *  Switch: '<S1028>/Switch4'
   */
  if (rtb_RelationalOperator_dp) {
    *rty_PredObjMotion = rtb_Product_mb * rtb_PredictedHeading +
      rtb_NewPosnLgt_j;
    *rty_PredObjMotion_g = rtb_Product_mb * rtb_Quotient_o2 + rtb_NewPosnLat_h;
  } else {
    *rty_PredObjMotion = rtb_NewPosnLgt_j;
    *rty_PredObjMotion_g = rtb_NewPosnLat_h;
  }

  /* End of Switch: '<S1028>/Switch3' */
}

/*
 * Output and update for action system:
 *    '<S986>/LinearPrediction'
 *    '<S1811>/LinearPrediction'
 */
void LongSafe_SWC_LinearPrediction(const ObjGroup1Vcc *rtu_Obj, const
  MotionType0 *rtu_MotionType, const SafetyMarginData *rtu_SafetyMarginData,
  real32_T rtu_PredictionTime, real32_T *rty_PredObjMotion, real32_T
  *rty_PredObjMotion_a, real32_T *rty_PredObjMotion_g, real32_T
  *rty_PredObjMotion_i, real32_T *rty_PredObjMotion_aw, real32_T
  *rty_PredObjMotion_h, real32_T *rty_PredObjAgDir)
{
  real32_T rtb_Quotient_c2;
  real32_T rtb_TrigonometricFunction_o;

  /* Outputs for Atomic SubSystem: '<S1055>/SafeDivide' */
  /* MATLAB Function: '<S1059>/SafeDivide' */
  if (fabsf(rtu_SafetyMarginData->ALgt) > fabsf(rtu_Obj->Estimn.VLgt) *
      5.42101151E-20F) {
    rtb_Quotient_c2 = rtu_Obj->Estimn.VLgt / rtu_SafetyMarginData->ALgt;
  } else if (rtu_Obj->Estimn.VLgt > 0.0F) {
    rtb_Quotient_c2 = LongSafe_SWC_DataTypeMax_o;
  } else if (rtu_Obj->Estimn.VLgt < 0.0F) {
    rtb_Quotient_c2 = LongSafe_SWC_DataTypeMin_g;
  } else {
    rtb_Quotient_c2 = 0.0F;
  }

  /* End of MATLAB Function: '<S1059>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S1055>/SafeDivide' */

  /* Gain: '<S1055>/Gain' */
  rtb_Quotient_c2 *= rtCP_Gain_Gain_h;

  /* Switch: '<S1055>/Switch' incorporates:
   *  Constant: '<S1058>/Constant'
   *  MinMax: '<S1055>/MinMax'
   *  RelationalOperator: '<S1058>/Compare'
   */
  if (rtb_Quotient_c2 > rtCP_Constant_Value_ga) {
    rtb_Quotient_c2 = fminf(rtu_PredictionTime, rtb_Quotient_c2);
  } else {
    rtb_Quotient_c2 = rtu_PredictionTime;
  }

  /* End of Switch: '<S1055>/Switch' */

  /* Sum: '<S1054>/Sum6' incorporates:
   *  Constant: '<S1054>/Constant'
   *  Product: '<S1054>/Product1'
   *  Product: '<S1054>/Product4'
   *  Product: '<S1054>/Product5'
   */
  *rty_PredObjMotion = rtb_Quotient_c2 * rtb_Quotient_c2 *
    rtu_SafetyMarginData->ALgt * rtCP_Constant_Value_ak + (rtu_Obj->Estimn.VLgt *
    rtb_Quotient_c2 + rtu_Obj->Estimn.PosnLgt);

  /* Switch: '<S1049>/Switch' incorporates:
   *  Abs: '<S1056>/Abs'
   *  Constant: '<S1049>/Constant'
   *  Constant: '<S1049>/Constant1'
   *  Constant: '<S1056>/LimitSource'
   *  Product: '<S1054>/Product6'
   *  RelationalOperator: '<S1056>/Relational Operator'
   *  Sum: '<S1049>/Add'
   *  Sum: '<S1054>/Sum3'
   *  Switch: '<S1049>/Switch1'
   */
  if (fabsf(rtu_PredictionTime - rtb_Quotient_c2) > rtCP_LimitSource_Value_f) {
    *rty_PredObjMotion_g = rtCP_Constant_Value_nj;
    rtb_Quotient_c2 = rtCP_Constant1_Value_kh4;
  } else {
    *rty_PredObjMotion_g = rtu_SafetyMarginData->ALgt;
    rtb_Quotient_c2 = rtb_Quotient_c2 * rtu_SafetyMarginData->ALgt +
      rtu_Obj->Estimn.VLgt;
  }

  /* End of Switch: '<S1049>/Switch' */

  /* Sum: '<S1050>/Sum3' incorporates:
   *  Product: '<S1050>/Product6'
   */
  rtb_TrigonometricFunction_o = rtu_PredictionTime * rtu_SafetyMarginData->ALat
    + rtu_Obj->Estimn.VLat;

  /* Sum: '<S1050>/Sum6' incorporates:
   *  Constant: '<S1050>/Constant'
   *  Product: '<S1050>/Product1'
   *  Product: '<S1050>/Product4'
   *  Product: '<S1050>/Product5'
   */
  *rty_PredObjMotion_i = rtu_PredictionTime * rtu_PredictionTime *
    rtu_SafetyMarginData->ALat * rtCP_Constant_Value_gkf + (rtu_Obj->Estimn.VLat
    * rtu_PredictionTime + rtu_Obj->Estimn.PosnLat);

  /* SignalConversion: '<S1051>/Signal Conversion' */
  *rty_PredObjMotion_a = rtb_Quotient_c2;

  /* SignalConversion: '<S1052>/Signal Conversion' */
  *rty_PredObjMotion_aw = rtb_TrigonometricFunction_o;

  /* SignalConversion: '<S1053>/Signal Conversion' */
  *rty_PredObjMotion_h = rtu_SafetyMarginData->ALat;

  /* Switch: '<S1024>/Switch_1' incorporates:
   *  Trigonometry: '<S1024>/Trigonometric Function'
   */
  if (rtu_MotionType->ObjectIsVehicle) {
    *rty_PredObjAgDir = rtu_Obj->Estimn.AgDir;
  } else {
    *rty_PredObjAgDir = rt_atan2f_snf(rtb_TrigonometricFunction_o,
      rtb_Quotient_c2);
  }

  /* End of Switch: '<S1024>/Switch_1' */
}

/*
 * Output and update for action system:
 *    '<S987>/StationaryObject'
 *    '<S1316>/StationaryObject'
 *    '<S1812>/StationaryObject'
 *    '<S2844>/StationaryObject'
 *    '<S2853>/StationaryObject'
 *    '<S2862>/StationaryObject'
 *    '<S2871>/StationaryObject'
 *    '<S2880>/StationaryObject'
 *    '<S3410>/StationaryObject'
 *    '<S3419>/StationaryObject'
 *    ...
 */
void LongSafe_SWC_StationaryObject(const BoundingBox0 *rtu_BoundingBox, real32_T
  rtu_PredictedHeadingObj, real32_T rtu_PredictedHeadingHost, real32_T
  *rty_SinRelativeRotation, real32_T *rty_CosRelativeRotation, real32_T
  *rty_RelativeHeading)
{
  real32_T rtb_Product_3_e;
  real32_T rtb_Product_4_f;

  /* Trigonometry: '<S1065>/Trigonometric Function' */
  rtb_Product_3_e = cosf(rtu_PredictedHeadingHost);

  /* Trigonometry: '<S1065>/Trigonometric Function1' */
  rtb_Product_4_f = sinf(rtu_PredictedHeadingHost);

  /* Sum: '<S1065>/Add1' incorporates:
   *  Product: '<S1065>/Product_1'
   *  Product: '<S1065>/Product_2'
   */
  *rty_SinRelativeRotation = rtb_Product_3_e * rtu_BoundingBox->SinRotation -
    rtb_Product_4_f * rtu_BoundingBox->CosRotation;

  /* Sum: '<S1065>/Add2' incorporates:
   *  Product: '<S1065>/Product_3'
   *  Product: '<S1065>/Product_4'
   */
  *rty_CosRelativeRotation = rtu_BoundingBox->CosRotation * rtb_Product_3_e +
    rtu_BoundingBox->SinRotation * rtb_Product_4_f;

  /* Sum: '<S1065>/Add3' */
  rtb_Product_3_e = rtu_PredictedHeadingObj - rtu_PredictedHeadingHost;

  /* Saturate: '<S1065>/Saturation' */
  if (rtb_Product_3_e > rtCP_Saturation_UpperSat_i) {
    rtb_Product_3_e = rtCP_Saturation_UpperSat_i;
  } else if (rtb_Product_3_e < rtCP_Saturation_LowerSat_h) {
    rtb_Product_3_e = rtCP_Saturation_LowerSat_h;
  }

  *rty_RelativeHeading = rtb_Product_3_e;

  /* End of Saturate: '<S1065>/Saturation' */
}

/*
 * Output and update for action system:
 *    '<S987>/MovingObject'
 *    '<S1316>/MovingObject'
 *    '<S1812>/MovingObject'
 *    '<S2844>/MovingObject'
 *    '<S2853>/MovingObject'
 *    '<S2862>/MovingObject'
 *    '<S2871>/MovingObject'
 *    '<S2880>/MovingObject'
 *    '<S3419>/MovingObject'
 *    '<S3428>/MovingObject'
 *    ...
 */
void LongSafe_SWC_MovingObject(real32_T rtu_PredictedHeadingHost, real32_T
  rtu_PredictedHeadingObj, boolean_T rtu_SideIsClosest, real32_T
  *rty_SinRelativeRotation, real32_T *rty_CosRelativeRotation, real32_T
  *rty_RelativeHeading, const ConstB_MovingObject_LongSafe_SWC_T *localC)
{
  real32_T rtb_CosLengthAngle;
  real32_T rtb_Modulus;
  real32_T rtb_Product2_l1;
  real32_T rtb_SinLengthAngle;

  /* Sum: '<S1064>/Subtract' */
  rtb_Modulus = rtu_PredictedHeadingObj - rtu_PredictedHeadingHost;

  /* Sum: '<S1066>/Subtract_2' incorporates:
   *  Constant: '<S1064>/Constant_1'
   *  Math: '<S1066>/Modulus'
   *  Sum: '<S1066>/Subtract_1'
   */
  rtb_SinLengthAngle = rtCP_Constant_1_Value - rt_modf_snf(rtCP_Constant_1_Value
    - rtb_Modulus, localC->Gain_1);

  /* Trigonometry: '<S1064>/cos' */
  rtb_CosLengthAngle = cosf(rtb_SinLengthAngle);

  /* Signum: '<S1064>/Sign1' */
  if (rtb_SinLengthAngle < 0.0F) {
    rtb_Product2_l1 = -1.0F;
  } else if (rtb_SinLengthAngle > 0.0F) {
    rtb_Product2_l1 = 1.0F;
  } else if (rtb_SinLengthAngle == 0.0F) {
    rtb_Product2_l1 = 0.0F;
  } else {
    rtb_Product2_l1 = (rtNaNF);
  }

  /* End of Signum: '<S1064>/Sign1' */

  /* Sum: '<S1067>/Subtract_2' incorporates:
   *  Constant: '<S1064>/Constant_2'
   *  Math: '<S1067>/Modulus'
   *  Sum: '<S1067>/Subtract_1'
   */
  *rty_RelativeHeading = rtCP_Constant_2_Value - rt_modf_snf
    (rtCP_Constant_2_Value - rtb_Modulus, localC->Gain_1_d);

  /* Trigonometry: '<S1064>/sin' */
  rtb_SinLengthAngle = sinf(rtb_SinLengthAngle);

  /* Switch: '<S1064>/Switch2' incorporates:
   *  Gain: '<S1064>/Gain_1'
   *  Product: '<S1064>/Product1'
   *  Product: '<S1064>/Product2'
   *  Switch: '<S1064>/Switch3'
   */
  if (rtu_SideIsClosest) {
    *rty_SinRelativeRotation = rtb_CosLengthAngle * rtb_Product2_l1 *
      rtCP_Gain_1_Gain_f;
    *rty_CosRelativeRotation = rtb_Product2_l1 * rtb_SinLengthAngle;
  } else {
    *rty_SinRelativeRotation = rtb_SinLengthAngle;
    *rty_CosRelativeRotation = rtb_CosLengthAngle;
  }

  /* End of Switch: '<S1064>/Switch2' */
}

/*
 * Output and update for atomic system:
 *    '<S1097>/QuadraticEquationSolver'
 *    '<S1116>/QuadraticEquationSolver'
 *    '<S1137>/QuadraticEquationSolver'
 *    '<S1156>/QuadraticEquationSolver'
 *    '<S1426>/QuadraticEquationSolver'
 *    '<S1445>/QuadraticEquationSolver'
 *    '<S1466>/QuadraticEquationSolver'
 *    '<S1485>/QuadraticEquationSolver'
 *    '<S1922>/QuadraticEquationSolver'
 *    '<S1941>/QuadraticEquationSolver'
 *    ...
 */
void LongSafe_SWC_QuadraticEquationSolver(real32_T rtu_a, real32_T rtu_b,
  real32_T rtu_c, real32_T rty_x[2], boolean_T *rty_SolutionFound)
{
  boolean_T aEqualsZero;
  aEqualsZero = ((rtu_a < rtCP_QuadraticEquationSolver_ZeroThreshold_l) &&
                 (rtu_a > -rtCP_QuadraticEquationSolver_ZeroThreshold_l));
  if (aEqualsZero && ((rtu_b < rtCP_QuadraticEquationSolver_ZeroThreshold_l) &&
                      (rtu_b > -rtCP_QuadraticEquationSolver_ZeroThreshold_l)))
  {
    *rty_SolutionFound = ((rtu_c < rtCP_QuadraticEquationSolver_ZeroThreshold_l)
                          && (rtu_c >
      -rtCP_QuadraticEquationSolver_ZeroThreshold_l));
    rty_x[0] = 0.0F;
    rty_x[1] = 0.0F;
  } else if (aEqualsZero) {
    real32_T squareRoot;
    *rty_SolutionFound = true;
    squareRoot = -rtu_c / rtu_b;
    rty_x[0] = squareRoot;
    rty_x[1] = squareRoot;
  } else {
    real32_T bSquared;
    real32_T squareRoot;
    bSquared = rtu_b * rtu_b;
    squareRoot = 4.0F * rtu_a * rtu_c;
    if (squareRoot > bSquared) {
      *rty_SolutionFound = false;
      rty_x[0] = 0.0F;
      rty_x[1] = 0.0F;
    } else {
      *rty_SolutionFound = true;
      squareRoot = sqrtf(bSquared - squareRoot);
      bSquared = (-rtu_b + squareRoot) / (2.0F * rtu_a);
      squareRoot = (-rtu_b - squareRoot) / (2.0F * rtu_a);
      if (bSquared > squareRoot) {
        rty_x[0] = bSquared;
        rty_x[1] = squareRoot;
      } else {
        rty_x[0] = squareRoot;
        rty_x[1] = bSquared;
      }
    }
  }
}

/*
 * Output and update for action system:
 *    '<S1079>/LeftClosest'
 *    '<S1080>/LeftClosest'
 */
void LongSafe_SWC_LeftClosest(real32_T rtu_VLatRel, real32_T rtu_ALatRel,
  real32_T rtu_EdgeDistanceLeftClosest, real32_T rtu_EdgeDistanceRightClosest,
  real32_T *rty_TimeToIntersection, const ConstB_LeftClosest_LongSafe_SWC_T
  *localC)
{
  /* local block i/o variables */
  real32_T rtb_x_e[2];
  real32_T rtb_ARelHalf_d;
  real32_T rtb_EdgeDistance;
  real32_T rtb_Gain_jy;
  real32_T rtb_Square_o;
  real32_T rtb_VLatRel_e;
  boolean_T rtb_NoSolution_p;
  boolean_T rtb_SolutionFound_a;

  /* Gain: '<S1095>/Gain' */
  rtb_Gain_jy = rtCP_Gain_Gain_g * rtu_ALatRel;

  /* Math: '<S1095>/Square' */
  rtb_Square_o = rtu_VLatRel * rtu_VLatRel;

  /* Outputs for Atomic SubSystem: '<S1100>/SafeDivide' */
  /* MATLAB Function: '<S1101>/SafeDivide' */
  if (fabsf(rtb_Gain_jy) > fabsf(rtb_Square_o) * 5.42101151E-20F) {
    rtb_Gain_jy = rtb_Square_o / rtb_Gain_jy;
  } else if (rtb_Square_o > 0.0F) {
    rtb_Gain_jy = LongSafe_SWC_DataTypeMax_c;
  } else if (rtb_Square_o < 0.0F) {
    rtb_Gain_jy = LongSafe_SWC_DataTypeMin_gs;
  } else {
    rtb_Gain_jy = 0.0F;
  }

  /* End of MATLAB Function: '<S1101>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S1100>/SafeDivide' */

  /* Switch: '<S1102>/Switch' incorporates:
   *  RelationalOperator: '<S1102>/UpperRelop'
   */
  if (rtb_Gain_jy < localC->Gain) {
    rtb_Square_o = localC->Gain;
  } else {
    rtb_Square_o = rtb_Gain_jy;
  }

  /* End of Switch: '<S1102>/Switch' */

  /* Switch: '<S1102>/Switch2' incorporates:
   *  Constant: '<S1100>/Constant5'
   *  RelationalOperator: '<S1102>/LowerRelop1'
   */
  if (rtb_Gain_jy > rtCP_Constant5_Value_ih) {
    rtb_Square_o = rtCP_Constant5_Value_ih;
  }

  /* End of Switch: '<S1102>/Switch2' */

  /* Logic: '<S1095>/Logop_3' incorporates:
   *  Constant: '<S1098>/Constant'
   *  Constant: '<S1099>/Constant'
   *  Logic: '<S1095>/Logop_1'
   *  Logic: '<S1095>/Logop_2'
   *  RelationalOperator: '<S1095>/Relop_1'
   *  RelationalOperator: '<S1095>/Relop_2'
   *  RelationalOperator: '<S1098>/Compare'
   *  RelationalOperator: '<S1099>/Compare'
   */
  rtb_SolutionFound_a = (((rtu_EdgeDistanceLeftClosest > rtb_Square_o) &&
    (rtu_ALatRel > rtCP_Constant_Value_mke)) || ((rtu_EdgeDistanceLeftClosest <
    rtb_Square_o) && (rtu_ALatRel < rtCP_Constant_Value_mr)));

  /* Gain: '<S1096>/Gain' incorporates:
   *  UnaryMinus: '<S1093>/Unary Minus'
   */
  rtb_Gain_jy = rtCP_Gain_Gain_j * -rtu_ALatRel;

  /* Math: '<S1096>/Square' incorporates:
   *  UnaryMinus: '<S1093>/Unary Minus1'
   */
  rtb_Square_o = -rtu_VLatRel * -rtu_VLatRel;

  /* Outputs for Atomic SubSystem: '<S1106>/SafeDivide' */
  /* MATLAB Function: '<S1107>/SafeDivide' */
  if (fabsf(rtb_Gain_jy) > fabsf(rtb_Square_o) * 5.42101151E-20F) {
    rtb_Gain_jy = rtb_Square_o / rtb_Gain_jy;
  } else if (rtb_Square_o > 0.0F) {
    rtb_Gain_jy = LongSafe_SWC_DataTypeMax_c;
  } else if (rtb_Square_o < 0.0F) {
    rtb_Gain_jy = LongSafe_SWC_DataTypeMin_gs;
  } else {
    rtb_Gain_jy = 0.0F;
  }

  /* End of MATLAB Function: '<S1107>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S1106>/SafeDivide' */

  /* Switch: '<S1108>/Switch' incorporates:
   *  RelationalOperator: '<S1108>/UpperRelop'
   */
  if (rtb_Gain_jy < localC->Gain_m) {
    rtb_Square_o = localC->Gain_m;
  } else {
    rtb_Square_o = rtb_Gain_jy;
  }

  /* End of Switch: '<S1108>/Switch' */

  /* Switch: '<S1108>/Switch2' incorporates:
   *  Constant: '<S1106>/Constant5'
   *  RelationalOperator: '<S1108>/LowerRelop1'
   */
  if (rtb_Gain_jy > rtCP_Constant5_Value_l) {
    rtb_Square_o = rtCP_Constant5_Value_l;
  }

  /* End of Switch: '<S1108>/Switch2' */

  /* Logic: '<S1093>/Logop_3' incorporates:
   *  Constant: '<S1104>/Constant'
   *  Constant: '<S1105>/Constant'
   *  Logic: '<S1096>/Logop_1'
   *  Logic: '<S1096>/Logop_2'
   *  Logic: '<S1096>/Logop_3'
   *  RelationalOperator: '<S1096>/Relop_1'
   *  RelationalOperator: '<S1096>/Relop_2'
   *  RelationalOperator: '<S1104>/Compare'
   *  RelationalOperator: '<S1105>/Compare'
   *  UnaryMinus: '<S1093>/Unary Minus'
   */
  rtb_NoSolution_p = (rtb_SolutionFound_a && (((rtu_EdgeDistanceRightClosest >
    rtb_Square_o) && (-rtu_ALatRel > rtCP_Constant_Value_dl5)) ||
    ((rtu_EdgeDistanceRightClosest < rtb_Square_o) && (-rtu_ALatRel <
    rtCP_Constant_Value_ep5))));

  /* Switch: '<S1093>/Switch_1' incorporates:
   *  Logic: '<S1093>/Logop_1'
   *  Switch: '<S1093>/Switch_2'
   *  Switch: '<S1093>/Switch_4'
   *  UnaryMinus: '<S1093>/Unary Minus3'
   */
  if (!rtb_SolutionFound_a) {
    /* Switch: '<S1093>/Switch_1' */
    rtb_VLatRel_e = rtu_VLatRel;

    /* Switch: '<S1093>/Switch_2' */
    rtb_EdgeDistance = rtu_EdgeDistanceLeftClosest;
    rtb_Gain_jy = rtu_ALatRel;
  } else {
    /* Switch: '<S1093>/Switch_1' incorporates:
     *  UnaryMinus: '<S1093>/Unary Minus2'
     */
    rtb_VLatRel_e = -rtu_VLatRel;

    /* Switch: '<S1093>/Switch_2' */
    rtb_EdgeDistance = rtu_EdgeDistanceRightClosest;
    rtb_Gain_jy = -rtu_ALatRel;
  }

  /* End of Switch: '<S1093>/Switch_1' */

  /* Gain: '<S1097>/Gain' */
  rtb_ARelHalf_d = rtCP_Gain_Gain_d * rtb_Gain_jy;

  /* MATLAB Function: '<S1097>/QuadraticEquationSolver' */
  LongSafe_SWC_QuadraticEquationSolver(rtb_ARelHalf_d, rtb_VLatRel_e,
    rtb_EdgeDistance, rtb_x_e, &rtb_SolutionFound_a);

  /* Switch: '<S1097>/Switch1' incorporates:
   *  Constant: '<S1097>/Constant1'
   *  Constant: '<S1097>/Constant3'
   *  Constant: '<S1110>/Constant'
   *  RelationalOperator: '<S1110>/Compare'
   */
  if (rtb_EdgeDistance < rtCP_Constant_Value_h4) {
    *rty_TimeToIntersection = -k_AEB_TiUpprLimInAsyEvlrCritEve;
  } else {
    *rty_TimeToIntersection = k_AEB_TiUpprLimInAsyEvlrCritEve;
  }

  /* End of Switch: '<S1097>/Switch1' */

  /* Switch: '<S1093>/Switch_3' incorporates:
   *  Constant: '<S1093>/TiUpprLimIn'
   *  Switch: '<S1097>/Switch2'
   */
  if (rtb_NoSolution_p) {
    *rty_TimeToIntersection = k_AEB_TiUpprLimInAsyEvlrCritEve;
  } else if (rtb_SolutionFound_a) {
    /* Switch: '<S1112>/Switch3' incorporates:
     *  Constant: '<S1113>/Constant'
     *  RelationalOperator: '<S1113>/Compare'
     */
    if (rtb_Gain_jy < rtCP_Constant_Value_b1) {
      /* Switch: '<S1097>/Switch2' */
      *rty_TimeToIntersection = rtb_x_e[0];
    } else {
      /* Switch: '<S1097>/Switch2' */
      *rty_TimeToIntersection = rtb_x_e[1];
    }

    /* End of Switch: '<S1112>/Switch3' */
  }

  /* End of Switch: '<S1093>/Switch_3' */
}

