  /* local block i/o variables */
  real32_T rtb_x_d[2];
  real32_T rtb_ARelHalf_n;
  real32_T rtb_EdgeDistance;
  real32_T rtb_Gain_bl;
  real32_T rtb_Square_d;
  real32_T rtb_Square_i;
  real32_T rtb_VLatRel_i;
  boolean_T rtb_NoSolution_e;
