  boolean_T rtb_TestOk_hs;
  boolean_T rtb_TestOk_lx;

  /* Product: '<S3093>/Product7' incorporates:
   *  Product: '<S3094>/Product7'
   */
  rtb_VPred_jm = rtu_Obj->Estimn.ALat * rtu_CosHeading;

  /* Sum: '<S3093>/Add2' incorporates:
   *  Gain: '<S3093>/Gain'
   *  Product: '<S3093>/Product6'
   *  Product: '<S3093>/Product7'
   */
  rtb_PositionChangeFromAcceleration_kh = rtCP_Gain_Gain_dj *
    rtu_Obj->Estimn.ALgt * rtu_SinHeading + rtb_VPred_jm;

  /* Sum: '<S3093>/Add3' incorporates:
   *  Gain: '<S3093>/Gain1'
   *  Product: '<S3093>/Product1'
   *  Product: '<S3093>/Product2'
   */
  rtb_ResultingALgt = rtCP_Gain1_Gain_ch * rtb_PositionChangeFromAcceleration_kh
    * rtu_SinHeading + rtu_AObjAvoidance * rtu_CosHeading;

  /* Sum: '<S3093>/Add4' incorporates:
   *  Product: '<S3093>/Product3'
   *  Product: '<S3093>/Product4'
   */
  rtb_ResultingALat = rtb_PositionChangeFromAcceleration_kh * rtu_CosHeading +
    rtu_AObjAvoidance * rtu_SinHeading;

  /* Outputs for Atomic SubSystem: '<S3179>/SafeDivide' */
  /* Outputs for Atomic SubSystem: '<S3127>/SafeDivide' */
  /* Outputs for Atomic SubSystem: '<S3106>/SafeDivide' */
  /* MATLAB Function: '<S3110>/SafeDivide' incorporates:
   *  MATLAB Function: '<S3131>/SafeDivide'
   *  MATLAB Function: '<S3183>/SafeDivide'
   */
  rtb_Quotient_k1 = fabsf(rtu_Obj->Estimn.VLgt) * 5.42101151E-20F;

  /* End of Outputs for SubSystem: '<S3127>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S3179>/SafeDivide' */
  if (fabsf(rtb_ResultingALgt) > rtb_Quotient_k1) {
    rtb_Quotient_cs = rtu_Obj->Estimn.VLgt / rtb_ResultingALgt;
  } else if (rtu_Obj->Estimn.VLgt > 0.0F) {
    rtb_Quotient_cs = LongSafe_SWC_DataTypeMax_cp;
  } else if (rtu_Obj->Estimn.VLgt < 0.0F) {
    rtb_Quotient_cs = LongSafe_SWC_DataTypeMin_oj;
  } else {
    rtb_Quotient_cs = 0.0F;
  }

  /* End of MATLAB Function: '<S3110>/SafeDivide' */
  /* End of Outputs for SubSystem: '<S3106>/SafeDivide' */

  /* Gain: '<S3106>/Gain' */
  rtb_PositionChangeFromAcceleration_kh = rtCP_Gain_Gain_p5 * rtb_Quotient_cs;

  /* Switch: '<S3106>/Switch' incorporates:
   *  Constant: '<S3109>/Constant'
   *  MinMax: '<S3106>/MinMax'
   *  RelationalOperator: '<S3109>/Compare'
   */
  if (rtb_PositionChangeFromAcceleration_kh > rtCP_Constant_Value_ps) {
    rtb_PositionChangeFromAcceleration_kh = fminf(rtu_TTR,
      rtb_PositionChangeFromAcceleration_kh);
  } else {
    rtb_PositionChangeFromAcceleration_kh = rtu_TTR;
  }

  /* End of Switch: '<S3106>/Switch' */

  /* SignalConversion generated from: '<S2972>/PosnObjAtTTR' incorporates:
   *  Constant: '<S3105>/Constant'
   *  Product: '<S3105>/Product1'
   *  Product: '<S3105>/Product4'
   *  Product: '<S3105>/Product5'
   *  Sum: '<S3105>/Sum6'
   */
  *rty_PosnObjAtTTR_k = rtb_PositionChangeFromAcceleration_kh *
    rtb_PositionChangeFromAcceleration_kh * rtb_ResultingALgt *
    rtCP_Constant_Value_kd3 + (rtu_Obj->Estimn.VLgt *
    rtb_PositionChangeFromAcceleration_kh + rtu_Obj->Estimn.PosnLgt);

  /* RelationalOperator: '<S3107>/Relational Operator' incorporates:
   *  Abs: '<S3107>/Abs'
   *  Constant: '<S3107>/LimitSource'
   *  Sum: '<S3098>/Add'
   */
